macro_rules! expect {
    ($token:ident, $sym:literal, $self:expr, $diags:expr) => {
        if let Token::$token = $self.current {
            $self.advance(false);
        } else {
            $self.error($diags, err![$self, $sym]);
        }
    };
}
#[allow(unused_macros)]
macro_rules! try_expect {
    ($token:ident, $sym:literal, $self:expr, $diags:expr) => {
        if let Token::$token = $self.current {
            $self.advance(false);
        } else {
            if $self.in_ordered_choice {
                return None;
            }
            $self.error($diags, err![$self, $sym]);
        }
    };
}

