    fn rule_comp_op(&mut self, diags: &mut Vec<Diagnostic>) {
        match self.current {
            Token::Lt => {
                expect!(Lt, "<", self, diags);
            }
            Token::Gt => {
                expect!(Gt, ">", self, diags);
            }
            Token::Eq2 => {
                expect!(Eq2, "==", self, diags);
            }
            Token::GtEq => {
                expect!(GtEq, ">=", self, diags);
            }
            Token::LtEq => {
                expect!(LtEq, "<=", self, diags);
            }
            Token::LtGt => {
                expect!(LtGt, "<>", self, diags);
            }
            Token::ExclEq => {
                expect!(ExclEq, "!=", self, diags);
            }
            Token::In => {
                expect!(In, "in", self, diags);
            }
            Token::Not => {
                expect!(Not, "not", self, diags);
                expect!(In, "in", self, diags);
            }
            Token::Is => {
                expect!(Is, "is", self, diags);
                match self.current {
                    Token::Not => {
                        expect!(Not, "not", self, diags);
                    }
                    Token::Await
                    | Token::BTick
                    | Token::FString
                    | Token::Float
                    | Token::Imaginary
                    | Token::Int
                    | Token::LBrace
                    | Token::LBrak
                    | Token::LPar
                    | Token::Minus
                    | Token::Name
                    | Token::Plus
                    | Token::String
                    | Token::Tilde => {}
                    _ => {
                        self.error(diags, err![self, "await",
                                    "`",
                                    "FString",
                                    "Float",
                                    "Imaginary",
                                    "Int",
                                    "{",
                                    "[",
                                    "(",
                                    "-",
                                    "Name",
                                    "not",
                                    "+",
                                    "String",
                                    "~"]);
                    }
                }
            }
            _ => {
                self.error(diags, err![self, "==",
                            "!=",
                            ">",
                            ">=",
                            "in",
                            "is",
                            "<",
                            "<=",
                            "<>",
                            "not"]);
            }
        }
    }
